mapper.update:
UPDATE inv_stocktake_line SET counted_quantity=#{countedQuantity},count_revision=count_revision+1,
  last_counter_user_id=#{counterUserId},counted_at=#{countedAt},updated_at=#{countedAt}
WHERE tenant_id=#{tenantId} AND stocktake_id=#{stocktakeId} AND line_id=#{lineId}
  AND count_revision=#{expectedRevision}

UPDATE inv_stocktake_line SET adjusted_book_quantity=#{adjustedBookQuantity},
  cutoff_ledger_sequence=#{cutoffLedgerSequence},variance_quantity=#{varianceQuantity},updated_at=#{updatedAt}
WHERE tenant_id=#{tenantId} AND stocktake_id=#{stocktakeId} AND line_id=#{lineId}

UPDATE inv_stocktake SET status=#{nextStatus},version=version+1,
  reviewer_user_id=COALESCE(#{reviewerUserId},reviewer_user_id),
  approver_user_id=COALESCE(#{approverUserId},approver_user_id),
  cutoff_at=COALESCE(#{cutoffAt},cutoff_at),posted_at=COALESCE(#{postedAt},posted_at),
  adjustment_event_id=COALESCE(#{adjustmentEventId},adjustment_event_id),updated_at=#{updatedAt}
WHERE tenant_id=#{tenantId} AND stocktake_id=#{stocktakeId}
  AND status=#{expectedStatus} AND version=#{expectedVersion}
